CREATE TEMP TABLE tmp_tree (ord int, id uuid, nm text, father uuid, gen int, branch text) ON COMMIT DROP;
WITH RECURSIVE chain AS (
  SELECT r.ord, r.nm, r.par, r.branch, r.nm::text AS disp, 1 AS gen FROM tmp_raw r WHERE r.par IS NULL
  UNION ALL
  SELECT r.ord, r.nm, r.par, r.branch, r.nm || ' بن ' || c.disp, c.gen + 1
  FROM tmp_raw r JOIN chain c ON r.par = c.ord
)
INSERT INTO tmp_tree (ord, id, nm, father, gen, branch)
SELECT c.ord, md5(c.disp)::uuid, c.nm,
       (SELECT md5(p.disp)::uuid FROM chain p WHERE p.ord = c.par),
       c.gen, c.branch
FROM chain c;

DELETE FROM public.family_relationships;
DELETE FROM public.family_member_privacy;
DELETE FROM public.family_members;

WITH RECURSIVE disp AS (
  SELECT id, nm::text AS d FROM tmp_tree WHERE father IS NULL
  UNION ALL
  SELECT t.id, t.nm || ' بن ' || p.d FROM tmp_tree t JOIN disp p ON t.father = p.id
)
INSERT INTO public.family_members (id, first_name_ar, last_name_ar, display_name_ar, slug, gender, is_living, generation, sort_order, visibility, status, branch_id)
SELECT t.id, t.nm, 'آل بوعبيد', d.d || ' آل بوعبيد',
       'm-' || left(t.id::text, 8), 'male', true, t.gen, t.ord, 'public', 'published', b.id
FROM tmp_tree t JOIN disp d ON d.id = t.id LEFT JOIN public.branches b ON b.slug = t.branch;

INSERT INTO public.family_relationships (person_id, related_person_id, relationship_type)
SELECT father, id, 'parent'::relationship_type FROM tmp_tree WHERE father IS NOT NULL
UNION ALL
SELECT id, father, 'child'::relationship_type FROM tmp_tree WHERE father IS NOT NULL;
